import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"37、【家人】 離下巽上","description":"子夏易傳 - 37、【家人】 離下巽上","frontmatter":{"title":"37、【家人】 離下巽上","description":"子夏易傳 - 37、【家人】 離下巽上"},"headers":[],"relativePath":"classics/zixia/039.md","filePath":"classics/zixia/039.md"}'),i={name:"classics/zixia/039.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_37、【家人】-離下巽上" tabindex="-1">37、【家人】 離下巽上 <a class="header-anchor" href="#_37、【家人】-離下巽上" aria-label="Permalink to “37、【家人】 離下巽上”">​</a></h1><p>卦辭：家人，利女貞。</p><p>彖曰：家人，女正位乎內，男正位乎外。男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父子子，兄兄弟弟，夫夫婦婦，而家道正。正家而天下定矣。</p><p>子夏：正家之道在於女正，女既位而男位正也。故聖人設昬禮焉，重而娶之，當其位也。然後可保其久矣。夫婦正，家道之先，上下之始也。嚴君之道始焉，父母之道出焉，故嚴其君。則父父子子，兄兄弟弟，夫夫婦婦，家道咸正，而天下定矣。</p><p>象曰：風自火出，家人。君子以言有物，而行有恆。</p><p>子夏：火出而風鼓之炎，乃大也。女正而男久之，家乃成也。必由內生而外成也。言必有在而不茍行，必守常而不雜此家人之，則而正其本也。</p><p>初九，閑有家，悔亡。</p><p>象曰：閑有家，志未變也。</p><p>子夏：家人之道，在於防邪，防閑在於初也。及其志未變而正之，則不至於悔矣。得之制者也。</p><p>六二，無攸遂，在中饋，貞吉。</p><p>象曰：六二之吉，順以巽也。</p><p>子夏：婦人之職，正其中也。無所遂其成，在中主饋而已。體柔順而剛巽之，得正之吉也。</p><p>九三，家人嗃嗃，悔厲吉。婦子嘻嘻，終吝。</p><p>象曰：家人嗃嗃，未失也。婦子嘻嘻，失家節也。</p><p>子夏：體之上，家之長，剛以嚴之。故嗃嗃，威下也。家人之性，不喜服也。雖悔有厲，乃保其吉也。婦子嘻嘻，從下之性，何以節其中哉，可惜也已</p><p>六四，富家大吉。</p><p>象曰：富家大吉，順在位也。</p><p>子夏：柔承於尊，位高而順，故得家之富，保其大吉也。</p><p>九五，王假有家，勿恤，吉。</p><p>象曰：王假有家，交相愛也。</p><p>子夏：剛尊配應，夫婦之正，而家道正矣。王至有家，天下刑於上也，親以相親，交以汎愛，何憂乎禍亂哉。故能保其吉也。</p><p>上九，有孚，威如，終吉。</p><p>象曰：威如之吉，反身之謂也。</p><p>子夏：剛得終於家人，天下化之，信而行之人。人正，家而自為治也。夫以家人，威信之道始以，令人也。其終也。反信已焉，人反敬已焉。威信及而天下之治至矣。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
